style:
* {
  font-family: "Fira Sans", sans-serif;
  font-size: 13px;
}
window#waybar {
  background: rgba(30, 30, 46, 0.9);
  color: #cdd6f4;
}
#workspaces button {
  padding: 0 6px;
  color: #585b70;
}
#workspaces button.active {
  color: #cdd6f4;
}
#clock, #network, #pulseaudio, #battery {
  padding: 0 10px;
}
